def odd_even_jumps(arr):
    n = len(arr)

    def next_index(i, want_ge):                                            # want_ge=True: smallest arr[j]>=arr[i]; False: largest arr[j]<=arr[i]
        best_j, best_val = -1, None
        for j in range(i + 1, n):
            if want_ge and arr[j] >= arr[i]:
                if best_val is None or arr[j] < best_val:
                    best_val, best_j = arr[j], j
            elif not want_ge and arr[j] <= arr[i]:
                if best_val is None or arr[j] > best_val:
                    best_val, best_j = arr[j], j
        return best_j

    good = 0
    for start in range(n):
        i, is_odd = start, True                                            # simulate the ENTIRE jump sequence from this start, directly
        while i != n - 1:
            j = next_index(i, is_odd)
            if j == -1:
                break
            i, is_odd = j, not is_odd
        if i == n - 1:
            good += 1
    return good


if __name__ == "__main__":
    print(odd_even_jumps([10, 13, 12, 14, 15]))

