import java.util.*;

public class Main {
    int oddEvenJumps(int[] arr) {
        int n = arr.length;
        int good = 0;
        for (int start = 0; start < n; start++) {
            int i = start;
            boolean isOdd = true;                                                     // simulate the ENTIRE jump sequence from this start, directly
            while (i != n - 1) {
                int bestJ = -1;
                Integer bestVal = null;
                for (int j = i + 1; j < n; j++) {
                    if (isOdd && arr[j] >= arr[i]) {
                        if (bestVal == null || arr[j] < bestVal) { bestVal = arr[j]; bestJ = j; }
                    } else if (!isOdd && arr[j] <= arr[i]) {
                        if (bestVal == null || arr[j] > bestVal) { bestVal = arr[j]; bestJ = j; }
                    }
                }
                if (bestJ == -1) break;
                i = bestJ;
                isOdd = !isOdd;
            }
            if (i == n - 1) good++;
        }
        return good;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] arr = {10, 13, 12, 14, 15};
        System.out.println(solution.oddEvenJumps(arr));
    }
}

