import java.util.*;

public class Main {
    int oddEvenJumps(int[] arr) {
        int n = arr.length;
        Integer[] ascByValue = new Integer[n];
        Integer[] descByValue = new Integer[n];
        for (int i = 0; i < n; i++) { ascByValue[i] = i; descByValue[i] = i; }
        Arrays.sort(ascByValue, (a, b) -> arr[a] != arr[b] ? arr[a] - arr[b] : a - b);          // for "next odd jump": smallest arr[j] >= arr[i]
        Arrays.sort(descByValue, (a, b) -> arr[a] != arr[b] ? arr[b] - arr[a] : a - b);         // for "next even jump": largest arr[j] <= arr[i]

        int[] nextOdd = makeNext(ascByValue, n);
        int[] nextEven = makeNext(descByValue, n);

        boolean[] canOdd = new boolean[n];
        boolean[] canEven = new boolean[n];
        canOdd[n - 1] = canEven[n - 1] = true;                                                    // the last index trivially "reaches itself" with 0 jumps
        int good = 1;
        for (int i = n - 2; i >= 0; i--) {                                                        // walk BACKWARD: whether i is good depends on later indices
            if (nextOdd[i] != -1) canOdd[i] = canEven[nextOdd[i]];                                    // an odd jump from i must be followed by a REACHABLE even-jump position
            if (nextEven[i] != -1) canEven[i] = canOdd[nextEven[i]];                                  // an even jump from i must be followed by a REACHABLE odd-jump position
            if (canOdd[i]) good++;                                                                    // the FIRST jump from any start is always odd-numbered
        }
        return good;
    }

    int[] makeNext(Integer[] order, int n) {
        int[] nextIdx = new int[n];
        Arrays.fill(nextIdx, -1);
        Deque<Integer> stack = new ArrayDeque<>();                                                    // a monotonic stack of indices, kept in INCREASING index order
        for (int i : order) {
            while (!stack.isEmpty() && stack.peek() < i) {                                                // i is a valid "target" for everything smaller-indexed waiting
                nextIdx[stack.pop()] = i;
            }
            stack.push(i);
        }
        return nextIdx;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] arr = {10, 13, 12, 14, 15};
        System.out.println(solution.oddEvenJumps(arr));
    }
}

