vector<int> makeNext(vector<int>& order, int n) {
    vector<int> nextIdx(n, -1);
    vector<int> stack;                                                                                // a monotonic stack of indices, kept in INCREASING index order
    for (int i : order) {
        while (!stack.empty() && stack.back() < i) {                                                     // i is a valid "target" for everything smaller-indexed waiting
            nextIdx[stack.back()] = i;
            stack.pop_back();
        }
        stack.push_back(i);
    }
    return nextIdx;
}

